SELECT transaction_id,transaction_type,transaction_quantity,transaction_date,transaction_flag,material_stock_id,
       source_doc_id,source_doc_code,source_doc_line_id,source_doc_type,related_transaction_id
FROM wm_transaction
WHERE source_doc_type=#{sourceDocType} AND source_doc_id=#{sourceDocId}
  AND source_doc_line_id=#{sourceDocLineId} AND workorder_id=#{workorderId}
ORDER BY transaction_date,transaction_id
